import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.C8822HRV.js";const h=JSON.parse('{"title":"Project folders after sdd init","description":"What folders sdd creates in your app — .sdd, memory, changes, and optional AI host files — explained simply.","frontmatter":{"title":"Project folders after sdd init","description":"What folders sdd creates in your app — .sdd, memory, changes, and optional AI host files — explained simply.","head":[["meta",{"property":"og:title","content":"Project folders after sdd init · sdd"}],["meta",{"property":"og:description","content":"What folders sdd creates in your app — .sdd, memory, changes, and optional AI host files — explained simply."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/reference/layout/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"Project folders after sdd init · sdd"}],["meta",{"name":"twitter:description","content":"What folders sdd creates in your app — .sdd, memory, changes, and optional AI host files — explained simply."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/reference/layout/"}]]},"headers":[],"relativePath":"reference/layout.md","filePath":"reference/layout.md","lastUpdated":1785895617000}'),o={name:"reference/layout.md"};function p(r,e,l,i,d,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="project-folders" tabindex="-1">Project folders <a class="header-anchor" href="#project-folders" aria-label="Permalink to &quot;Project folders&quot;">​</a></h1><p>After <code>sdd init</code>, your app looks roughly like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.sdd/                 ← sdd settings and the short playbook</span></span>
<span class="line"><span>  config.yaml</span></span>
<span class="line"><span>  protocol.md         ← rules for you + the AI</span></span>
<span class="line"><span>  active-context.md   ← what you’re doing right now</span></span>
<span class="line"><span>  handoff.md          ← brief the AI just saw</span></span>
<span class="line"><span>  mcp.yaml            ← external MCP sources sdd calls (optional)</span></span>
<span class="line"><span>  workflows/          ← paths like hotfix, feature, greenfield</span></span>
<span class="line"><span>  templates/</span></span>
<span class="line"><span>memory/               ← longer-lived product notes (keep short)</span></span>
<span class="line"><span>  index.md</span></span>
<span class="line"><span>  constitution.md     ← non-negotiables</span></span>
<span class="line"><span>  …</span></span>
<span class="line"><span>changes/              ← one folder per piece of work</span></span>
<span class="line"><span>  &lt;id&gt;/</span></span>
<span class="line"><span>    meta.yaml         ← stage + status</span></span>
<span class="line"><span>    *.md              ← short notes for this work</span></span>
<span class="line"><span>domains/              ← optional extra docs by area</span></span>
<span class="line"><span>AGENTS.md             ← tiny pointer for AIs</span></span>
<span class="line"><span># only for the AI you picked:</span></span>
<span class="line"><span># .github/agents/  or  .grok/rules/  or  .claude/agents/  or  .ollama/</span></span></code></pre></div><h3 id="optional-external-mcp-sources" tabindex="-1">Optional: external MCP sources <a class="header-anchor" href="#optional-external-mcp-sources" aria-label="Permalink to &quot;Optional: external MCP sources&quot;">​</a></h3><p><code>sdd init</code> creates an empty <strong><code>.sdd/mcp.yaml</code></strong>. Register design-system / org / AST servers with <code>sdd mcp sources add …</code> so sdd can pull context at the right stage. See <a href="./../guides/mcp">MCP sources</a>.</p><p>After a <strong>new product</strong> path finishes, you may also see:</p><ul><li><code>memory/product.md</code></li><li><code>memory/requirements.md</code></li><li><code>memory/features.md</code></li><li><code>memory/architecture.md</code></li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../concepts/change-packs">Change packs &amp; memory</a></li><li><a href="./../guides/agents">Set up your AI</a></li><li><a href="./../guides/mcp">MCP sources</a></li></ul>`,9)])])}const u=a(o,[["render",p]]);export{h as __pageData,u as default};
